SELECT DATABASE() AS approved_database,VERSION() AS mysql_version;
SELECT table_name,column_name,ordinal_position,column_type,is_nullable,column_default,extra FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('res_project','res_project_leader','res_project_lab','res_project_tag','res_project_member','res_batch','res_batch_leader','res_batch_member','res_culture','res_culture_leader','res_culture_member','res_culture_occupancy','res_culture_notice_outbox','res_culture_parameter_application','res_culture_parameter_snapshot','res_culture_parameter_state','res_culture_workflow_reference','res_culture_runtime_event') ORDER BY table_name,ordinal_position;
SELECT table_name,index_name,seq_in_index,column_name,non_unique FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('res_project','res_project_leader','res_project_lab','res_project_tag','res_project_member','res_batch','res_batch_leader','res_batch_member','res_culture','res_culture_leader','res_culture_member','res_culture_occupancy','res_culture_notice_outbox','res_culture_parameter_application','res_culture_parameter_snapshot','res_culture_parameter_state','res_culture_workflow_reference','res_culture_runtime_event') ORDER BY table_name,index_name,seq_in_index;
SELECT 'res_culture' AS source_table,COUNT(*) AS baseline_rows FROM `res_culture`;
SELECT 'res_culture_occupancy' AS source_table,COUNT(*) AS baseline_rows FROM `res_culture_occupancy`;
